#include <iostream>
#include <cstring>
#include <string_view>

int main() {
    const char* s1 = "Happy New Year";
    const char* s2 = "Happy New Year";
    const char* s3 = "Happy Holidays";

    // Testing strcmp
    std::cout << "strcmp(s1, s2) == 0: " << (std::strcmp(s1, s2) == 0 ? "true" : "false") << "\n";
    std::cout << "strcmp(s1, s3): " << (std::strcmp(s1, s3) > 0 ? "> 0" : "<= 0") << "\n";
    std::cout << "strcmp(s3, s1): " << (std::strcmp(s3, s1) < 0 ? "< 0" : ">= 0") << "\n";

    // Testing strncmp with prefix length
    std::cout << "strncmp(s1, s3, 6): " << std::strncmp(s1, s3, 6) << " (matching 'Happy ')\n";
    std::cout << "strncmp(s1, s3, 7): " << (std::strncmp(s1, s3, 7) > 0 ? "> 0" : "<= 0") << "\n";

    // Modern C++17 comparison with string_view
    std::string_view sv1{s1};
    std::string_view sv3{s3};
    std::cout << "C++17 string_view (sv1 == sv3): " << std::boolalpha << (sv1 == sv3) << "\n";

    return 0;
}

#include <iostream>
#include <cstring>

int main() {
    // Must be a mutable char array, NEVER a string literal (CERT STR06-C)
    char sentence[] = "This is a sentence with 7 tokens";

    std::cout << "Original before strtok: " << sentence << "\n";
    std::cout << "Tokens:\n";

    char *tokenPtr = std::strtok(sentence, " ");
    while (tokenPtr != nullptr) {
        std::cout << tokenPtr << "\n";
        tokenPtr = std::strtok(nullptr, " ");
    }

    // Notice sentence[4] was replaced by '\0'
    std::cout << "First word remaining in buffer: " << sentence << "\n";
    return 0;
}

#include <iostream>
#include <cstdlib>

int main() {
    // strtod demonstration
    const char *floatStr = "51.2% are admitted";
    char *floatRemainder = nullptr;
    double d = std::strtod(floatStr, &floatRemainder);
    std::cout << "strtod: " << d << " | remainder: \"" << floatRemainder << "\"\n";

    // strtol with base 0 (auto-detect)
    const char *intStr = "-1234567abc";
    char *intRemainder = nullptr;
    long x = std::strtol(intStr, &intRemainder, 0);
    std::cout << "strtol: " << x << " | remainder: \"" << intRemainder << "\"\n";

    // strtoul with explicit base 16 (hexadecimal)
    const char *hexStr = "1A3Fxyz";
    char *hexRemainder = nullptr;
    unsigned long u = std::strtoul(hexStr, &hexRemainder, 16);
    std::cout << "strtoul (hex): " << u << " | remainder: \"" << hexRemainder << "\"\n";

    return 0;
}
